package funcs

import (
	"fmt"
	"path/filepath"
)

// FilePath is the filepath namespace object. Methods become template
// functions like filepath.Base. Wrappers around Go's path/filepath package.
type FilePath struct{}

func init() {
	RegisterNS("filepath", func(deps *Deps) interface{} { return FilePath{} })
}

// pathArgToString converts an arbitrary template argument to a string the
// way gomplate does for path-like inputs: untyped nil renders as "nil",
// everything else uses fmt's default %v formatting.
func pathArgToString(in interface{}) string {
	if in == nil {
		return "nil"
	}
	return fmt.Sprintf("%v", in)
}

// Base returns the last element of path.
func (FilePath) Base(path interface{}) string {
	return filepath.Base(pathArgToString(path))
}

// Clean returns the shortest path name equivalent to path.
func (FilePath) Clean(path interface{}) string {
	return filepath.Clean(pathArgToString(path))
}

// Dir returns all but the last element of path.
func (FilePath) Dir(path interface{}) string {
	return filepath.Dir(pathArgToString(path))
}

// Ext returns the file name extension used by path.
func (FilePath) Ext(path interface{}) string {
	return filepath.Ext(pathArgToString(path))
}

// FromSlash replaces each slash with the platform's separator character.
func (FilePath) FromSlash(path interface{}) string {
	return filepath.FromSlash(pathArgToString(path))
}

// IsAbs reports whether the path is absolute.
func (FilePath) IsAbs(path interface{}) bool {
	return filepath.IsAbs(pathArgToString(path))
}

// Join joins any number of path elements into a single path.
func (FilePath) Join(elem ...interface{}) string {
	elems := make([]string, len(elem))
	for i, e := range elem {
		elems[i] = pathArgToString(e)
	}
	return filepath.Join(elems...)
}

// Match reports whether name matches the shell file name pattern.
func (FilePath) Match(pattern, name interface{}) (bool, error) {
	return filepath.Match(pathArgToString(pattern), pathArgToString(name))
}

// Rel returns a relative path to targetpath from basepath.
func (FilePath) Rel(basepath, targetpath interface{}) (string, error) {
	return filepath.Rel(pathArgToString(basepath), pathArgToString(targetpath))
}

// Split splits path into a directory and file name component, returned as
// a two-element array.
func (FilePath) Split(path interface{}) []string {
	dir, file := filepath.Split(pathArgToString(path))
	return []string{dir, file}
}

// ToSlash replaces each separator character with a slash.
func (FilePath) ToSlash(path interface{}) string {
	return filepath.ToSlash(pathArgToString(path))
}

// VolumeName returns the leading volume name.
func (FilePath) VolumeName(path interface{}) string {
	return filepath.VolumeName(pathArgToString(path))
}

