// Path is the path namespace object. Methods become template functions
// like path.Base. Wrappers around Go's path package (always slash-based).
type Path struct{}

func init() {
	RegisterNS("path", func(deps *Deps) interface{} { return Path{} })
}

// Base returns the last element of path.
func (Path) Base(p interface{}) string {
	return path.Base(pathArgToString(p))
}

// Clean returns the shortest path name equivalent to path.
func (Path) Clean(p interface{}) string {
	return path.Clean(pathArgToString(p))
}

// Dir returns all but the last element of path.
func (Path) Dir(p interface{}) string {
	return path.Dir(pathArgToString(p))
}

// Ext returns the file name extension used by path.
func (Path) Ext(p interface{}) string {
	return path.Ext(pathArgToString(p))
}

// IsAbs reports whether the path is absolute.
func (Path) IsAbs(p interface{}) bool {
	return path.IsAbs(pathArgToString(p))
}

// Join joins any number of path elements into a single path.
func (Path) Join(elem ...interface{}) string {
	elems := make([]string, len(elem))
	for i, e := range elem {
		elems[i] = pathArgToString(e)
	}
	return path.Join(elems...)
}

// Match reports whether name matches the shell file name pattern.
func (Path) Match(pattern, name interface{}) (bool, error) {
	return path.Match(pathArgToString(pattern), pathArgToString(name))
}

// Split splits path into a directory and file name component, returned as
// a two-element array.
func (Path) Split(p interface{}) []string {
	dir, file := path.Split(pathArgToString(p))
	return []string{dir, file}
}

