func TestFilePathBase(t *testing.T) {
	fp := FilePath{}
	cases := []struct {
		in  interface{}
		out string
	}{
		{"/tmp/foo", "foo"},
		{"", "."},
		{"/", "/"},
		{42, "42"},
		{3.14, "3.14"},
		{4.0, "4"},
		{nil, "nil"},
		{`a\b`, `a\b`}, // backslash is not a separator on linux
	}
	for _, c := range cases {
		if got := fp.Base(c.in); got != c.out {
			t.Errorf("Base(%v) = %q, want %q", c.in, got, c.out)
		}
	}
}

func TestFilePathCleanDirExt(t *testing.T) {
	fp := FilePath{}
	if got := fp.Clean("/tmp//foo/../"); got != "/tmp" {
		t.Errorf("Clean = %q", got)
	}
	if got := fp.Dir("/tmp/foo"); got != "/tmp" {
		t.Errorf("Dir = %q", got)
	}
