	}
}

func TestFilePathMatch(t *testing.T) {
	fp := FilePath{}
	ok, err := fp.Match("*.csv", "foo.csv")
	if err != nil || !ok {
		t.Errorf("Match = %v, %v", ok, err)
	}
	ok, err = fp.Match("", "x")
	if err != nil || ok {
		t.Errorf("Match empty pattern = %v, %v", ok, err)
	}
	if _, err = fp.Match("[", "x"); err == nil || err.Error() != "syntax error in pattern" {
		t.Errorf("Match bad pattern err = %v", err)
	}
}

func TestFilePathRel(t *testing.T) {
